                             "pass": bool(gate_ic and gate_icir)}
    print(f"=== {name} ===")
    print(f"  window: {factor_w.index.min().date()} .. {factor_w.index.max().date()}, "
          f"{len(factor_w)} dates, {panel.shape[1]} assets")
